s/        \/\/ Core fires no event for the module link lifecycle; log the decision\.\n        if \(\$created\) \{\n            \\local_dimensions\\event\\module_link_added::create\(\[\n                'context' => \$modcontext,\n                'objectid' => \(int\) \$link->get\('id'\),\n                'other' => \['competencyid' => \$competencyid, 'cmid' => \$cmid\],\n            \]\)->trigger\(\);\n        \}/        \\local_dimensions\\event\\module_link_added::create([\n            'context' => \$modcontext,\n            'objectid' => (int) \$link->get('id'),\n            'other' => ['competencyid' => \$competencyid, 'cmid' => \$cmid],\n        ])->trigger();/;
